[L2]   "content": "{
  "manifest_version": 3,
  "name": "Scribd Premium Downloader",
  "version": "2.9.0",
  "description": "Professional suite for managing, backing up, and downloading Scribd documents. Native support for Original PDF and HQ Scan.",
  "permissions": [
    "activeTab",
    "scripting",
    "tabs",
    "downloads",
    "storage"
  ],
  "host_permissions": [
    "<all_urls>"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_popup": "popup.html",
    "default_icon": {
      "16": "icons/icon16.png",
      "32": "icons/icon32.png",
      "48": "icons/icon48.png",
      "128": "icons/icon128.png"
    }
  },
  "icons": {
    "16": "icons/icon16.png",
    "32": "icons/icon32.png",
    "48": "icons/icon48.png",
    "128": "icons/icon128.png"
  },
  "content_scripts": [
    {
      "matches": [
        "*://*.scribd.com/*"
      ],
      "all_frames": false,
      "js": [
        "libs/shim.js",
        "libs/html2canvas.min.js",
        "libs/jspdf.umd.min.js",
        "libs/i18n.js",
        "content.js"
      ],
      "css": [
        "overlay.css"
      ],
      "run_at": "document_idle"
    }
  ],
  "web_accessible_resources": [
    {
      "resources": [
        "libs/html2canvas.min.js",
        "libs/jspdf.umd.min.js",
        "libs/shim.js",
        "libs/i18n.js",
        "icons/icon128.png",
        "icons/icon48.png",
        "icons/icon32.png"
      ],
      "matches": [
        "<all_urls>"
      ]
    }
  ]
}",
